?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout — ShahkotPK Shop</title><link rel="stylesheet" href="/assets/themes/landing/base.css?v=240"><link rel="stylesheet" href="/assets/live-commerce-3.4.0.css?v=340"></head><body class="lc-page"><header class="lc-public-header"><div class="lt-shell"><a class="lc-public-brand" href="/cart.php">← Checkout</a></div></header><section class="shop-section"><div class="lt-shell checkout-grid"><form method="post" class="shop-panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><h2>Delivery / Buyer Information</h2><?php if($err):?><div style="padding:9px;background:#fee2e2;color:#991b1b;border-radius:9px"><?=e($err)?></div><?php endif;?><label>Name</label><input name="name" value="<?=e($u['name'])?>" required><label>Phone</label><input name="phone" value="<?=e($u['phone'])?>" required><label>Email</label><input name="email" value="<?=e($u['email'])?>"><label>Address</label><textarea name="address" <?=$cart['has_digital']?'':'required'?>></textarea><label>City</label><input name="city" value="<?=e(setting('default_city','Shahkot'))?>"><label>Payment</label><select name="payment_method"><?php if(!empty($cart['allow_cod'])&&setting_bool('store_cod_enabled',true)):?><option value="cod">Cash on Delivery</option><?php endif;?><?php if(!empty($cart['allow_advance'])&&setting_bool('store_advance_enabled',true)):?><option value="advance">Advance Payment</option><?php endif;?></select><label>Order Notes</label><textarea name="notes"></textarea><button class="cv-primary-btn" style="border:0;width:100%;margin-top:14px">Place Order</button></form><aside class="shop-panel"><h3>Order Total</h3><?php foreach($cart['items'] as $row):?><p><?=e($row['product']['title'])?> × <?=e($row['qty'])?><b style="float:right">Rs <?=e(number_format($row['line_total'],0))?></b></p><?php endforeach;?><hr><p>Grand Total <b style="float:right;font-size:21px">Rs <?=e(